import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const bg = colors.background ?? '#0b0b10';
  const surface = colors.surface ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const gradTop = colors.gradientStops?.[0]?.hex ?? '#ff4450';
  const gradBot = colors.gradientStops?.[1]?.hex ?? '#c1121f';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const first = (role) => byRole(role)[0]?.text ?? '';

  const root = new Group();
  const timelines = [];
  const disposables = [];

  // ---- Backdrop stage ----
  const bgMat = new MeshBasicNodeMaterial();
  {
    const vY = uv().y;
    const cTop = color(new Color(bg).offsetHSL(0, 0, 0.04));
    const cBot = color(bg);
    bgMat.colorNode = mix(cBot, cTop, vY);
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdrop.geometry, bgMat);

  // ---- Lights ----
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(-3, 4, 4);
  root.add(key);

  const rim = new DirectionalLight(new Color(accent).getHex(), 0.9);
  rim.position.set(3, -2, 3);
  root.add(rim);

  // ---- Card body ----
  const cardGroup = new Group();
  root.add(cardGroup);

  const cardW = 2.4;
  const cardH = 3.2;

  const cardMat = new MeshStandardNodeMaterial();
  cardMat.color = new Color(surface);
  cardMat.roughness = 0.6;
  cardMat.metalness = 0.2;
  const card = new Mesh(new BoxGeometry(cardW, cardH, 0.06), cardMat);
  card.position.set(0, 0, 0);
  cardGroup.add(card);
  disposables.push(card.geometry, cardMat);

  // hairline border
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.color = new Color('#2a2a33');
  const border = new Mesh(new PlaneGeometry(cardW + 0.012, cardH + 0.012), borderMat);
  border.position.set(0, 0, -0.032);
  cardGroup.add(border);
  disposables.push(border.geometry, borderMat);

  // ---- Machined header strip ----
  const headerMat = new MeshPhysicalNodeMaterial();
  headerMat.color = new Color('#3a3a44');
  headerMat.roughness = 0.55;
  headerMat.metalness = 0.5;
  headerMat.clearcoat = 0.2;
  headerMat.clearcoatRoughness = 0.4;
  const header = new Mesh(new BoxGeometry(cardW, 0.08, 0.07), headerMat);
  header.position.set(0, cardH / 2 - 0.04, 0.005);
  cardGroup.add(header);
  disposables.push(header.geometry, headerMat);

  // ---- Text layer helper ----
  const zText = 0.05;
  const padTop = cardH / 2 - 0.5;

  const addText = (content, opts, x, y) => {
    if (!content) return null;
    const t = ctx.fontAtlas.createText(content, opts);
    t.position.set(x, y, zText);
    cardGroup.add(t);
    return t;
  };

  const leftX = -cardW / 2 + 0.5;

  // Tier name
  addText(first('tier-name'), { fontSize: 20, color: paper, align: 'left', letterSpacingPx: 3 }, leftX, padTop - 0.12);

  // Price
  addText(first('price'), { fontSize: 62, color: paper, align: 'left' }, leftX, padTop - 0.5);

  // caption
  addText(first('caption'), { fontSize: 9, color: '#8a8a95', align: 'left', letterSpacingPx: 2 }, leftX, padTop - 0.82);

  // ---- Feature rows ----
  const features = byRole('feature');
  const featureTexts = [];
  const rowStartY = padTop - 1.35;
  const rowStep = 0.375;

  features.forEach((f, i) => {
    const y = rowStartY - i * rowStep;
    const t = addText(f.text, { fontSize: 13, color: paper, align: 'left' }, leftX, y);
    if (t) featureTexts.push(t);

    // hairline separator
    const sepMat = new MeshBasicNodeMaterial();
    sepMat.color = new Color('#23232b');
    const sep = new Mesh(new PlaneGeometry(cardW - 1.0, 0.006), sepMat);
    sep.position.set(0, y - rowStep / 2 + 0.05, zText - 0.01);
    cardGroup.add(sep);
    disposables.push(sep.geometry, sepMat);
  });

  // ---- CTA row ----
  const ctaGroup = new Group();
  const ctaW = 1.4;
  const ctaH = 0.36;
  const ctaMat = new MeshStandardNodeMaterial();
  {
    const vY = uv().y;
    ctaMat.colorNode = mix(color(gradBot), color(gradTop), vY);
    ctaMat.emissiveNode = mix(color(gradBot), color(gradTop), vY).mul(float(0.6));
    ctaMat.roughness = 0.5;
    ctaMat.metalness = 0.1;
  }
  const cta = new Mesh(new PlaneGeometry(ctaW, ctaH), ctaMat);
  ctaGroup.add(cta);
  disposables.push(cta.geometry, ctaMat);

  const ctaGlowMat = new MeshBasicNodeMaterial();
  ctaGlowMat.color = new Color(accent);
  const ctaGlow = new Mesh(new PlaneGeometry(ctaW + 0.02, ctaH + 0.02), ctaGlowMat);
  ctaGlow.position.z = -0.005;
  ctaGroup.add(ctaGlow);
  disposables.push(ctaGlow.geometry, ctaGlowMat);

  const ctaLabel = ctx.fontAtlas.createText(first('cta-label'), {
    fontSize: 13, color: colors.ink ?? '#16161d', align: 'center', letterSpacingPx: 3
  });
  ctaLabel.position.set(0, 0, 0.01);
  ctaGroup.add(ctaLabel);

  ctaGroup.position.set(0, -cardH / 2 + 0.5 + ctaH / 2, zText);
  cardGroup.add(ctaGroup);

  // ---- Motion ----
  // weighted settle
  cardGroup.scale.setScalar(1.04);
  const settle = gsap.to(cardGroup.scale, {
    x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out'
  });
  timelines.push(settle);

  // header specular band drag
  const headerDrag = gsap.fromTo(header.position, { x: -0.4 }, { x: 0, duration: 0.9, ease: 'power3.out' });
  timelines.push(headerDrag);

  // feature stagger fade-up
  featureTexts.forEach((t, i) => {
    const baseY = t.position.y;
    t.position.y = baseY + 0.2;
    if (t.material) t.material.opacity = 0;
    const tl = gsap.timeline({ delay: 0.3 + i * 0.08 });
    tl.to(t.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    if (t.material) {
      t.material.transparent = true;
      tl.to(t.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    }
    timelines.push(tl);
  });

  // idle breathing
  const breathe = gsap.to(cardGroup.rotation, {
    y: 0.03, duration: 4, ease: 'sine.inOut', yoyo: true, repeat: -1, delay: 1
  });
  timelines.push(breathe);

  // ---- Handlers ----
  root.userData.handlers = {
    click: () => {
      const press = gsap.timeline();
      press.to(ctaGroup.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
      press.to(ctaGroup.scale, { x: 1, y: 1, duration: 0.18, ease: 'power2.out' });
      timelines.push(press);
      ctx.emit('checkout:begin', { itemId: 'atelier-reserve' });
    },
    hover: (hovering) => {
      gsap.to(ctaGlow.scale, {
        x: hovering ? 1.05 : 1, y: hovering ? 1.05 : 1, duration: 0.3, ease: 'power2.out'
      });
    }
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => d?.dispose?.());
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return root;
}
